"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3256],{8127(e){e.exports=JSON.parse('{"title":"Memoization \ub2e8\uacc4\ubcc4\ub85c \uad6c\ud604\ud558\uae30","date":"2024-06-19","coverUrl":null,"html":"<h2 data-notion-block-id=\\"4d4acef3-eeba-4eea-ae7a-84917f84f105\\" id=\\"4d4acef3-eeba-4eea-ae7a-84917f84f105\\">Memoization \ub2e8\uacc4\ubcc4\ub85c \uad6c\ud604\ud558\uae30</h2><a href=\\"https://dev.to/thekashey/weak-memoization-in-javascript-4po6\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dev.to/thekashey/weak-memoization-in-javascript-4po6</a><p data-notion-block-id=\\"8c0fa114-2b0e-4b58-bce2-5d101d853511\\"><b>\uc2ec\uc724\uc12d</b>: \ud074\ub85c\uc800, This, \uadf8\ub9ac\uace0 Weakmap\uc744 \uc18c\uac1c\ud558\uba74\uc11c reselect\uc758 \uad6c\ud604\uc744 \ub2e8\uacc4\uc801\uc73c\ub85c \ub2e4\uac00\uac00\ub294 \uae00\uc785\ub2c8\ub2e4. JS\uc758 \uc911\uc694\ud55c \uac1c\ub150\ub4e4\uc744 \uce5c\uc808\ud788 \uc124\uba85\ud558\uba74\uc11c \ub2e4\uac00\uac00\uae30 \ub54c\ubb38\uc5d0 \uaf2d \uc77d\uc5b4\ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4. \ubc88\uc678\ub85c WeakMap\uc774 \uc608\uc2dc\ub85c \ub4e4\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac \uc678\uc5d0\ub3c4 memoization\uc744 \uc704\ud574 \ub9ce\uc774 \uc4f0\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4(ex. <a href=\\"https://blog.axlight.com/posts/you-might-not-need-react-query-for-jotai/\\">Jotai</a>).</p><h2 data-notion-block-id=\\"7d25bf57-fc00-4550-af60-f285baddad43\\" id=\\"7d25bf57-fc00-4550-af60-f285baddad43\\">HTMX\uc758 \ub2e8\uc21c\ud568</h2><a href=\\"https://www.erikheemskerk.nl/htmx-simplicity/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.erikheemskerk.nl/htmx-simplicity/</a><p data-notion-block-id=\\"25a63c5e-e23b-4a9d-afdf-e94538cc00e7\\"><b>\uc2ec\uc724\uc12d</b>: \uc800\uc790\ub294 \uc740\ud0c4\ud658\uc740 \uc5c6\ub2e4\ub77c\ub294 \uac83\uc744 \ub9d0\ud558\uba74\uc11c\ub3c4 \uac04\ub2e8\ud55c UI\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\ub97c \ub108\ubb34 \ub9ce\uc774 \uc0ac\uc6a9\ud55c\ub2e4\ub294 \uac83\uc744 \ub3d9\uc2dc\uc5d0 \ub9d0\ud569\ub2c8\ub2e4. \uadf8\ub7ec\uba74\uc11c \uac04\ub2e8\ud55c UI\ub97c \ub9cc\ub4e0\ub2e4\uba74 htmx\uc815\ub3c4\uba74 \uad1c\ucc2e\ub2e4\ub294 \uc8fc\uc7a5\uc744 \ud3bc\uce58\ub294 \uae00\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc JS \ud504\ub808\uc784\uc6cc\ud06c\uc5d0 \uc775\uc219\ud574\uc9c4 \uac1c\ubc1c\uc790\ub4e4\uacfc \ub9ce\uc740 \uc778\ud130\ub809\uc158\uc744 \uc6d0\ud558\ub294 \uc694\uad6c\uc0ac\ud56d\uc5d0 \ub9de\ucdb0\uc11c HTMX\uc744 \ub9ce\uc774 \uc4f8 \uc218 \uc788\uc744\uc9c0\ub294 \uc758\ubb38\uc774 \ub4dc\ub124\uc694.</p><h2 data-notion-block-id=\\"8401be1c-6d02-47b0-90d6-4ae08ac46459\\" id=\\"8401be1c-6d02-47b0-90d6-4ae08ac46459\\">Valibot 0.31 \ucd9c\uc2dc</h2><a href=\\"https://valibot.dev/blog/valibot-v0.31.0-is-finally-available/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://valibot.dev/blog/valibot-v0.31.0-is-finally-available/</a><p data-notion-block-id=\\"d2410ca1-a084-46c1-99b3-e078b00ad0e3\\"><b>\uc2ec\uc724\uc12d</b>: zod\uac00 \ucd9c\uc2dc\ub418\uba74\uc11c schema \uac80\uc99d \ub3c4\uad6c\ub85c\uc11c \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc774\uc6a9\ub418\uc5c8\uc2b5\ub2c8\ub2e4. Valibot\uc740 zod\uc640 \ube44\uc2b7\ud55c \uad6c\uc870\ub97c \uc774\uc5b4\uac00\uba74\uc11c Tree shaking, \uc791\uc740 \ubc88\ub4e4\uc0ac\uc774\uc988\ub97c \ubaa9\ud45c\ub85c \ub9cc\ub4e4\uc5b4\uc84c\uc2b5\ub2c8\ub2e4. Valibot\uc740 \uc801\uc740 \ubc88\ub4e4\uc0ac\uc774\uc988\ub85c \ub9ce\uc740 \uc720\uc5f0\uc131\uc744 \ubaa9\ud45c\ub85c \uacc4\uc18d \uac1c\ubc1c\ud558\uace0 \uc788\uc73c\ubbc0\ub85c \uacc4\uc18d \uc9c0\ucf1c\ubcfc\ub9cc\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ubc88\uc678\ub85c \uc5ec\ub7ec Schema \uac80\uc99d \ub3c4\uad6c\ub97c \ube44\uc2b7\ud55c \uc778\ud130\ud398\uc774\uc2a4\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ub178\ub825\uc774 \ub2f4\uaca8\uc788\ub294 <a href=\\"https://github.com/decs/typeschema\\"><code>typeschema</code></a>\ub098 <a href=\\"https://github.com/standard-schema/standard-schema\\"><code>standard-schema</code></a>\ub3c4 \uacc4\uc18d \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"011c26fc-e180-4b41-b912-007040d7fa76\\" id=\\"011c26fc-e180-4b41-b912-007040d7fa76\\">\ud611\uc5c5 \uae30\ub2a5 \uad6c\ud604\uc744 \uc704\ud55c \uc544\ud0a4\ud14d\uccd0</h2><a href=\\"https://mattweidner.com/2024/06/04/server-architectures.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://mattweidner.com/2024/06/04/server-architectures.html</a><p data-notion-block-id=\\"b146833e-28a1-4489-827a-80a7a91618c3\\"><b>\uc2ec\uc724\uc12d</b>: \ud611\uc5c5 \uae30\ub2a5\uc744 \uad6c\ud604\ud558\uae30 \uc704\ud574(ex. Google Docs, Notion\u2026) \uc11c\ubc84\uc5d0\uc11c \ub2e4\ub978 \ubcc0\uacbd\uc0ac\ud56d\uc774 \ub4e4\uc5b4\uc654\uc744 \uacbd\uc6b0 \ucc98\ub9ac\ud558\ub294 \ubc29\uc2dd\uc744 \uad6c\ud604\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub9ce\uc774 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ud611\uc5c5 \uae30\ub2a5\uc744 \uad6c\ud604\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc774 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \uc0c1\uc138\ud558\uac8c \uc124\uba85\ud569\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \ubd84\uc0b0 \ud611\uc5c5 \uc11c\ubc84\ub3c4 \uc18c\uac1c\ud558\uace0 \uc788\uc5b4 \uae30\uc874 \uc911\uc559 \uc11c\ubc84 \ucc98\ub9ac \ubc29\uc2dd\uc758 \uc54c\uace0\ub9ac\uc998\uacfc \ud5a5\ud6c4 \ub098\uc544\uac08 \ubc29\ud5a5\uc744 \uc54c\uae30 \uc704\ud574 \uac00\ubccd\uac8c \ubcfc\ub9cc\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"110a330e-5d04-4c3f-8450-05b7a8c43375\\" id=\\"110a330e-5d04-4c3f-8450-05b7a8c43375\\">\ucd9c\uc2dc \uc8fc\uac04</h2><a href=\\"https://devblogs.microsoft.com/typescript/announcing-typescript-5-5-rc/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devblogs.microsoft.com/typescript/announcing-typescript-5-5-rc/</a><a href=\\"https://astro.build/blog/astro-4100/#rewrite-for-all-http-methods\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://astro.build/blog/astro-4100/#rewrite-for-all-http-methods</a><a href=\\"https://deno.com/blog/v1.44\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://deno.com/blog/v1.44</a><p data-notion-block-id=\\"34f7ddde-44f8-478e-93b7-16621aad7c3f\\">TypeScript 5.5\uc5d0\uc11c\uc758 \ucd94\ub860 \uac15\ud654, \uc815\uaddc\ud45c\ud604\uc2dd \uac80\uc0ac, \uc120\uc5b8 \ud30c\uc77c \uc9c0\uc6d0 \uac15\ud654, \uc81c\uc548\ub2e8\uacc4\uc758 Set \uba54\uc18c\ub4dc \uc9c0\uc6d0..\uc744 \ucd9c\uc2dc\ud560 \uac83\uc774\ub77c\uace0 \uc608\uace0\ud558\uc600\uace0, Astro\uc758 \ud658\uacbd \ubcc0\uc218 \uac80\uc0ac, \ubbf8\ub4e4\uc6e8\uc5b4 \uc7ac\uc791\uc131\u2026 \uae30\ub2a5\uacfc \ud568\uaed8 4.10\uc774 \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4. Deno\ub294 \ube44\uacf5\uac1c npm \uc800\uc7a5\uc18c, Node.js \ud638\ud658\uc131 \uc9c0\uc6d0\uacfc \uc131\ub2a5 \ud5a5\uc0c1\uc744 \uac00\uc9c4 1.44\ub97c \ucd9c\uc2dc\ud588\ub124\uc694.</p><h2 data-notion-block-id=\\"6e947f37-d04f-41c5-8898-9f0ab795f62d\\" id=\\"6e947f37-d04f-41c5-8898-9f0ab795f62d\\">NodeJS\uc5d0\uc11c setTimeout \uba54\ubaa8\ub9ac \ub204\uc218</h2><a href=\\"https://lucumr.pocoo.org/2024/6/5/node-timeout/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lucumr.pocoo.org/2024/6/5/node-timeout/</a><p data-notion-block-id=\\"e7ec45dc-c061-4d11-b03b-fb9e15f9e176\\">NodeJS\uc5d0\uc11c <code>setTimeout</code>\uc774 \ube0c\ub77c\uc6b0\uc800\uc640 \ub2e4\ub974\uac8c \uac1d\uccb4\ub97c \ubc18\ud658\ud558\ub294\ub370, \uac1d\uccb4\uc5d0 closure\uc5d0 \uad00\ud55c \uac83\uc744 \uc800\uc7a5\ud558\uae30 \ub54c\ubb38\uc5d0 \uba54\ubaa8\ub9ac \ub204\uc218\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f76c771b-c8fa-434e-aede-2a315473dc3f\\" id=\\"f76c771b-c8fa-434e-aede-2a315473dc3f\\">\ud30c\ub77c\ubbf8\ud130\uac00 \uc5ec\ub7ec\uac1c\uc77c \uacbd\uc6b0 \ud568\uc218\ub97c \ud569\uc131\ud558\ub294 \ubc29\ubc95</h2><a href=\\"https://jrsinclair.com/articles/2024/how-to-compose-functions-that-take-multiple-parameters-epic-guide/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jrsinclair.com/articles/2024/how-to-compose-functions-that-take-multiple-parameters-epic-guide/</a><p data-notion-block-id=\\"fdd96522-0b2b-4130-90b9-0e8a63559544\\">\ud568\uc218\ud615 \ud504\ub85c\uadf8\ub798\ubc0d \uac1c\ub150\uc5d0 \ud569\uc131\uc774\ub77c\ub294 \uac1c\ub150\uc744 \uc0ac\uc6a9\ud558\ub824\uba74 \ub9e4\uac1c\ubcc0\uc218\uac00 \uc77c\uc815\ud574\uc57c\ud558\ub294\ub370, \uc774\ub97c \ubcf5\ud569\uc801 \ub370\uc774\ud130\uad6c\uc870\ub098 \ucee4\ub9c1\uc744 \ud1b5\ud574 \ud574\uacb0\ud558\ub294 \ubc29\ubc95\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5db98a0c-a3e3-4653-af36-2e962a76c5b7\\" id=\\"5db98a0c-a3e3-4653-af36-2e962a76c5b7\\">FlatList \uc131\ub2a5 \ucd5c\uc801\ud654\ud558\uae30</h2><a href=\\"https://www.andydevs.dev/articles/flatlist-rendering-techniques\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.andydevs.dev/articles/flatlist-rendering-techniques</a><p data-notion-block-id=\\"5c5e8496-35cb-44b7-afac-11301ac22ce1\\">React Native\uc5d0\uc11c\ub294 \ubcf4\ud1b5 \ub9ac\uc2a4\ud2b8\ub97c \ubcf4\uc5ec\uc8fc\uae30 \uc704\ud574 <a href=\\"https://github.com/Shopify/flash-list\\">FlashList</a>\ub97c \uc0ac\uc6a9\ud558\ub294\ub370, \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc744 \uacbd\uc6b0 FlatList\ub97c \uc131\ub2a5 \ucd5c\uc801\ud654\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"654234f1-9bdb-486e-a33c-89b20cb2a7bc\\" id=\\"654234f1-9bdb-486e-a33c-89b20cb2a7bc\\">Vector DB\ub780 \ubb34\uc5c7\uc778\uac00\uc694?</h2><a href=\\"https://learn.microsoft.com/en-us/semantic-kernel/memories/vector-db\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://learn.microsoft.com/en-us/semantic-kernel/memories/vector-db</a><p data-notion-block-id=\\"4c360e40-6358-4dd8-9eef-c2e35205982c\\">\ub9ce\uc740 DB \uc11c\ube44\uc2a4\ud615 \ud68c\uc0ac\uc5d0\uc11c Vector DB\ub97c \uc18c\uac1c\ud558\ub294 \uae40\uc5d0, Vector DB\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc744 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p>"}')}}]);